import{d as b,V as o,X as s,$ as t,k as l,a8 as p,G as g,F as h,Z as m,aa as i,a0 as e,f as u,_ as y,a3 as f,W as c}from"./vendor-Cm8GqOYV.js";import{a9 as w}from"./index-C7hIbkqs.js";import"./ant-design-DpoBeJk5.js";import"./microvideo-map-DtJOnaGT.js";const k={class:"intro-page"},x={class:"page-header"},S={class:"header-links"},A={class:"tabs-container"},I={class:"tabs-header"},q=["onClick"],L={class:"tabs-content"},C={key:0,class:"tab-panel"},P={key:1,class:"tab-panel"},F={key:2,class:"tab-panel"},R={key:3,class:"tab-panel"},V=b({__name:"Intro",setup(j){const d=u("Skills+Shell"),r=[{id:"Skills+Shell",label:"第一代架构（Skills+Shell）"},{id:"langgraph",label:"第二代架构（LangGraph）"},{id:"tech-comparison",label:"技术选型对比"},{id:"topology",label:"平台能力拓扑图"}];return(_,a)=>{const n=o("router-link");return c(),s("div",k,[t("div",x,[a[1]||(a[1]=t("h1",null,"感智晓界系统架构介绍",-1)),a[2]||(a[2]=t("p",{class:"subtitle"},"智能体协助开发平台设计思路",-1)),t("div",S,[l(n,{to:"/generator",class:"header-link"},{default:p(()=>[...a[0]||(a[0]=[g("← 返回开发界面",-1)])]),_:1})])]),t("div",A,[t("div",I,[(c(),s(h,null,m(r,v=>t("button",{key:v.id,class:y(["tab-btn",{active:d.value===v.id}]),onClick:G=>d.value=v.id},f(v.label),11,q)),64))]),t("div",L,[d.value==="Skills+Shell"?(c(),s("div",C,[...a[3]||(a[3]=[i('<section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>架构示意图</h2><div class="architecture-diagram linear" data-v-a900c6ba><div class="arch-title" data-v-a900c6ba>线性顺序执行</div><div class="arch-flow" data-v-a900c6ba><div class="arch-node" data-v-a900c6ba>Preview</div><div class="arch-arrow" data-v-a900c6ba>→</div><div class="arch-node" data-v-a900c6ba>Figma</div><div class="arch-arrow" data-v-a900c6ba>→</div><div class="arch-node" data-v-a900c6ba>Reqd</div><div class="arch-arrow" data-v-a900c6ba>→</div><div class="arch-node" data-v-a900c6ba>Req</div><div class="arch-arrow" data-v-a900c6ba>→</div><div class="arch-node" data-v-a900c6ba>Reqs</div></div><div class="arch-note" data-v-a900c6ba> 每个阶段必须等待前一阶段完成，无法并行处理 </div></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>Skills驱动的工作流架构</h2><p data-v-a900c6ba>第一代系统采用<strong data-v-a900c6ba>Skills + Shell脚本结合的顺序工作流</strong>，通过mc-gen.cjs脚本编排，调用Claude AI的skills执行5个阶段：</p><div class="highlight-box" style="margin-bottom:16px;" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>技术特点：</strong></p><p data-v-a900c6ba> ✓ <strong data-v-a900c6ba>Shell脚本编排</strong>：mc-gen.cjs作为调度中枢，通过命令行参数控制流程<br data-v-a900c6ba> ✓ <strong data-v-a900c6ba>Skills智能执行</strong>：每个阶段调用预定义的AI技能，负责智能决策和代码生成<br data-v-a900c6ba> ✓ <strong data-v-a900c6ba>文件系统状态</strong>：使用文件作为状态存储和阶段间数据传递 </p></div><div class="process-flow" data-v-a900c6ba><div class="flow-step" data-v-a900c6ba><span class="step-num" data-v-a900c6ba>1</span><div class="step-content" data-v-a900c6ba><h3 data-v-a900c6ba>Preview 阶段（预览图生成）</h3><p data-v-a900c6ba>下载Figma预览图，使用AI识别图片结构，生成可运行的基础代码框架</p></div></div><div class="flow-arrow" data-v-a900c6ba>↓</div><div class="flow-step" data-v-a900c6ba><span class="step-num" data-v-a900c6ba>2</span><div class="step-content" data-v-a900c6ba><h3 data-v-a900c6ba>Figma 阶段（样式精修）</h3><p data-v-a900c6ba>获取Figma节点的详细数据，精确还原颜色、字体、边框、圆角、阴影等样式</p></div></div><div class="flow-arrow" data-v-a900c6ba>↓</div><div class="flow-step" data-v-a900c6ba><span class="step-num" data-v-a900c6ba>3</span><div class="step-content" data-v-a900c6ba><h3 data-v-a900c6ba>Req-d 阶段（配置设计）</h3><p data-v-a900c6ba>分析需求并生成/更新&quot;微码组件设计&quot;配置段落到requirement.md，不修改代码</p><small data-v-a900c6ba>仅生成配置文档，供人工审核后再注入代码</small></div></div><div class="flow-arrow" data-v-a900c6ba>↓</div><div class="flow-step" data-v-a900c6ba><span class="step-num" data-v-a900c6ba>4</span><div class="step-content" data-v-a900c6ba><h3 data-v-a900c6ba>Req 阶段（需求改造）</h3><p data-v-a900c6ba>根据requirement.md文档，实现业务接口、事件、状态等交互逻辑</p><small data-v-a900c6ba>单个AI负责，一次性生成</small></div></div><div class="flow-arrow" data-v-a900c6ba>↓</div><div class="flow-step" data-v-a900c6ba><span class="step-num" data-v-a900c6ba>5</span><div class="step-content" data-v-a900c6ba><h3 data-v-a900c6ba>Req-s 阶段（配置增强）</h3><p data-v-a900c6ba>将配置注入到代码中，增强组件的业务能力（事件、状态、接口调用等）</p><small data-v-a900c6ba>根据Req-d生成的配置进行代码增强</small></div></div></div><div class="highlight-box warn" style="margin-top:20px;" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>核心特点：</strong></p><p data-v-a900c6ba>✓ 顺序执行，前一阶段完成才能开始下一阶段<br data-v-a900c6ba> ✓ 每个阶段独立运行，彼此不交互<br data-v-a900c6ba> ✗ 无并行处理，总耗时较长<br data-v-a900c6ba> ✗ 无智能体协作和对抗验证机制</p></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>为什么需要Skills + 脚本？</h2><div class="why-need-box" data-v-a900c6ba><div class="why-item" data-v-a900c6ba><h3 data-v-a900c6ba>为什么需要Skills（AI智能）？</h3><p data-v-a900c6ba>脚本只能做确定性操作，无法处理需要&quot;理解&quot;和&quot;判断&quot;的任务：</p><ul data-v-a900c6ba><li data-v-a900c6ba>✕ <strong data-v-a900c6ba>脚本无法理解自然语言</strong>：&quot;帮我生成节点2-9778的微码组件&quot; → Skills能理解意图</li><li data-v-a900c6ba>✕ <strong data-v-a900c6ba>脚本无法生成代码</strong>：看Figma设计稿生成合理的Vue代码 → Skills能智能生成</li><li data-v-a900c6ba>✕ <strong data-v-a900c6ba>脚本无法做质量判断</strong>：代码是否符合规范 → Skills能语义级审查</li></ul><p class="summary" data-v-a900c6ba>✓ <strong data-v-a900c6ba>Skills = 大脑</strong>，提供智能决策、理解、生成能力</p></div><div class="why-item" data-v-a900c6ba><h3 data-v-a900c6ba>为什么需要脚本（流程控制）？</h3><p data-v-a900c6ba>AI无法精确控制系统操作和外部集成：</p><ul data-v-a900c6ba><li data-v-a900c6ba>✕ <strong data-v-a900c6ba>AI无法精确控制流程</strong>：按顺序创建目录、下载文件、保存状态 → 脚本能确定性执行</li><li data-v-a900c6ba>✕ <strong data-v-a900c6ba>AI无法调用外部API</strong>：调用Figma API获取节点数据 → 脚本能HTTP请求</li><li data-v-a900c6ba>✕ <strong data-v-a900c6ba>AI无法持久化状态</strong>：保存nodeId、阶段信息到文件 → 脚本能读写文件系统</li><li data-v-a900c6ba>✕ <strong data-v-a900c6ba>AI无法恢复中断</strong>：失败时保存checkpoint → 脚本能实现恢复机制</li></ul><p class="summary" data-v-a900c6ba>✓ <strong data-v-a900c6ba>脚本 = 手脚</strong>，提供精确控制、系统集成、状态管理能力</p></div></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>技术组成：Skills + 脚本</h2><p data-v-a900c6ba>第一代架构的核心是<strong data-v-a900c6ba>Skills（AI智能）</strong>和<strong data-v-a900c6ba>Shell脚本（流程控制）</strong>的结合：</p><div class="tech-components" data-v-a900c6ba><div class="component-box" data-v-a900c6ba><h3 data-v-a900c6ba>Skills（AI智能单元）</h3><ul data-v-a900c6ba><li data-v-a900c6ba><strong data-v-a900c6ba>frontend-mc-leader</strong>：总调度器，理解用户意图，协调整个工作流</li><li data-v-a900c6ba><strong data-v-a900c6ba>frontend-mc-developer</strong>：开发执行者，根据Figma数据生成Vue代码</li><li data-v-a900c6ba><strong data-v-a900c6ba>frontend-mc-code-reviewer</strong>：代码审查，检查代码质量和规范</li><li data-v-a900c6ba><strong data-v-a900c6ba>frontend-mc-guideline</strong>：规范指导，提供编码最佳实践</li></ul><div class="role-tag" data-v-a900c6ba>作用：理解、生成、判断</div></div><div class="component-box" data-v-a900c6ba><h3 data-v-a900c6ba>脚本（流程控制）</h3><ul data-v-a900c6ba><li data-v-a900c6ba><strong data-v-a900c6ba>mc-gen.cjs</strong>：核心调度脚本（333KB），控制5阶段流程</li><li data-v-a900c6ba><strong data-v-a900c6ba>config.cjs</strong>：配置管理，环境变量和路径配置</li><li data-v-a900c6ba><strong data-v-a900c6ba>pattern-matcher.cjs</strong>：代码模式检查，验证规范</li><li data-v-a900c6ba><strong data-v-a900c6ba>setup-skills.sh</strong>：Skills安装脚本</li></ul><div class="role-tag" data-v-a900c6ba>作用：调度、控制、持久化</div></div></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>配合工作示例</h2><p data-v-a900c6ba>以生成c-test组件的Preview阶段为例，展示Skills和脚本的协作过程：</p><div class="workflow-example" data-v-a900c6ba><div class="workflow-step" data-v-a900c6ba><div class="step-number" data-v-a900c6ba>1</div><div class="step-detail" data-v-a900c6ba><div class="step-actor skill" data-v-a900c6ba>Skills</div><div class="step-action" data-v-a900c6ba>用户：&quot;帮我生成节点2-9778的微码组件，命名为c-test&quot;</div><div class="step-result" data-v-a900c6ba>frontend-mc-leader 理解意图 → 解析参数 → 决策调用mc-gen脚本</div></div></div><div class="workflow-step" data-v-a900c6ba><div class="step-number" data-v-a900c6ba>2</div><div class="step-detail" data-v-a900c6ba><div class="step-actor script" data-v-a900c6ba>脚本</div><div class="step-action" data-v-a900c6ba>mc-gen.cjs 执行确定性操作</div><div class="step-result" data-v-a900c6ba>创建目录 → 调用Figma API → 下载预览图 → 准备AI提示词</div></div></div><div class="workflow-step" data-v-a900c6ba><div class="step-number" data-v-a900c6ba>3</div><div class="step-detail" data-v-a900c6ba><div class="step-actor skill" data-v-a900c6ba>Skills</div><div class="step-action" data-v-a900c6ba>frontend-mc-developer 智能生成</div><div class="step-result" data-v-a900c6ba>&quot;看懂&quot;预览图布局 → 结合Figma数据 → 生成完整Vue代码</div></div></div><div class="workflow-step" data-v-a900c6ba><div class="step-number" data-v-a900c6ba>4</div><div class="step-detail" data-v-a900c6ba><div class="step-actor script" data-v-a900c6ba>脚本</div><div class="step-action" data-v-a900c6ba>mc-gen.cjs 保存结果</div><div class="step-result" data-v-a900c6ba>写入index.vue → 保存状态到env.json → 生成declare.json</div></div></div><div class="workflow-step" data-v-a900c6ba><div class="step-number" data-v-a900c6ba>5</div><div class="step-detail" data-v-a900c6ba><div class="step-actor skill" data-v-a900c6ba>Skills</div><div class="step-action" data-v-a900c6ba>frontend-mc-code-reviewer 质量审查</div><div class="step-result" data-v-a900c6ba>检查代码规范 → 判断PASS/BLOCK → 决定是否继续</div></div></div><div class="workflow-step" data-v-a900c6ba><div class="step-number" data-v-a900c6ba>6</div><div class="step-detail" data-v-a900c6ba><div class="step-actor skill" data-v-a900c6ba>Skills</div><div class="step-action" data-v-a900c6ba>frontend-mc-leader 汇报结果</div><div class="step-result" data-v-a900c6ba>向用户报告：Preview阶段完成 → 建议继续Figma阶段</div></div></div></div><div class="highlight-box" style="margin-top:16px;background:var(--success-bg);border-left-color:var(--success);" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>协作要点：</strong></p><p data-v-a900c6ba><strong data-v-a900c6ba>Skills负责智能部分</strong>：理解需求、生成代码、审查质量、汇报结果<br data-v-a900c6ba><strong data-v-a900c6ba>脚本负责确定性部分</strong>：流程控制、API调用、文件操作、状态管理<br data-v-a900c6ba><strong data-v-a900c6ba>两者互补</strong>：Skills = 大脑（智能），脚本 = 手脚（执行） </p></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>优点与局限</h2><div class="pros-cons" data-v-a900c6ba><div class="pros" data-v-a900c6ba><h3 data-v-a900c6ba>优点</h3><ul data-v-a900c6ba><li data-v-a900c6ba>线性流程清晰，易于理解和维护</li><li data-v-a900c6ba>整体开发时间较短（30-60秒）</li><li data-v-a900c6ba>对简单组件效果不错，适合快速原型</li><li data-v-a900c6ba>代码结构简洁，没有复杂的抽象</li></ul></div><div class="cons" data-v-a900c6ba><h3 data-v-a900c6ba>局限</h3><ul data-v-a900c6ba><li data-v-a900c6ba><strong data-v-a900c6ba>单一AI负责生成</strong>：没有专门化分工，布局和样式混在一起</li><li data-v-a900c6ba><strong data-v-a900c6ba>缺乏验证机制</strong>：AI生成后直接输出，没有自动质量检查</li><li data-v-a900c6ba><strong data-v-a900c6ba>无法自动修复</strong>：发现问题后需要人工重新生成或手动修改</li><li data-v-a900c6ba><strong data-v-a900c6ba>依赖人工经验</strong>：质量完全取决于开发人员的检查能力</li><li data-v-a900c6ba><strong data-v-a900c6ba>复杂组件准确率低</strong>：多层嵌套、特殊效果容易出错</li></ul></div></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>实际效果</h2><p data-v-a900c6ba> 经过项目实践，第一代系统在<strong data-v-a900c6ba>简单组件</strong>（如数据卡片）上表现良好， 但面对<strong data-v-a900c6ba>复杂布局</strong>（如多层级嵌套、特殊动画）时，准确率仅约50%， 需要开发人员投入大量时间修正。 </p></section>',7)])])):e("",!0),d.value==="langgraph"?(c(),s("div",P,[...a[4]||(a[4]=[i('<section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>为什么需要第二代？</h2><p data-v-a900c6ba> 第一代系统的核心问题是：<strong data-v-a900c6ba>顺序执行效率低，单一AI质量不稳定，缺乏验证和纠错机制</strong>。 </p><div class="highlight-box warn" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>第一代的痛点：</strong></p><p data-v-a900c6ba> ✕ Preview和Figma阶段顺序执行，浪费时间<br data-v-a900c6ba> ✕ 单个AI一次性生成代码，容易出错<br data-v-a900c6ba> ✕ 没有验证机制，问题只能靠人工发现<br data-v-a900c6ba> ✕ 无法自动修复，需要人工介入或重新生成 </p></div><p style="margin-top:20px;" data-v-a900c6ba>而最根本的原因在于：<strong data-v-a900c6ba>单角色自检存在&quot;既当运动员又当裁判员&quot;的问题</strong>，同一个 AI 无法客观评价自己的输出。</p><div class="adversarial-flow" data-v-a900c6ba><div class="adversarial-step l1" data-v-a900c6ba><div class="step-badge" data-v-a900c6ba>L1</div><div class="step-info" data-v-a900c6ba><h3 data-v-a900c6ba>Vision 真实性检查</h3><p data-v-a900c6ba>AI 是否真的看到了图片？</p><span class="step-check" data-v-a900c6ba>检测：占位符、空字段、sections 数量</span></div></div><div class="adversarial-arrow" data-v-a900c6ba>→</div><div class="adversarial-step l2" data-v-a900c6ba><div class="step-badge" data-v-a900c6ba>L2</div><div class="step-info" data-v-a900c6ba><h3 data-v-a900c6ba>代码溯源检查</h3><p data-v-a900c6ba>代码是否来自 Vision？</p><span class="step-check" data-v-a900c6ba>检测：臆造文本、数值、padding、margin</span></div></div><div class="adversarial-arrow" data-v-a900c6ba>→</div><div class="adversarial-step l3" data-v-a900c6ba><div class="step-badge" data-v-a900c6ba>L3</div><div class="step-info" data-v-a900c6ba><h3 data-v-a900c6ba>交叉验证</h3><p data-v-a900c6ba>Vision 与 Code 是否一致？</p><span class="step-check" data-v-a900c6ba>对比：布局、元素、主题、图表类型</span></div></div></div><div class="key-insight" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>核心洞察</strong>：不要让写代码的人检查自己是否看了图，让一个独立的人 (Agent) 拿着图来对照代码。</p></div><h3 style="margin-top:24px;font-size:15px;color:var(--error-text);font-weight:700;" data-v-a900c6ba>这是单智能体的根本弊端</h3><p style="margin-top:8px;color:var(--text-secondary);line-height:1.8;" data-v-a900c6ba><strong data-v-a900c6ba>为什么单智能体 Loop 不行？</strong><br data-v-a900c6ba> 理论上，让同一个模型循环&quot;生成→自我检查→修订&quot;也能跑起来。但这里有个致命缺陷：<strong data-v-a900c6ba>检查者和生成者共享同一套推理过程</strong>——模型天然倾向于认可自己的结论。就像让学生批改自己的试卷，他永远能找到理由给自己满分。<br data-v-a900c6ba><br data-v-a900c6ba> 这就是单智能体无法逾越的边界：<strong data-v-a900c6ba>它永远是对的，因为它的判断依据和生成依据来自同一个推理空间</strong>。你让它检查自己的代码，它就检查自己推导的过程本身——这怎么可能发现错误？<br data-v-a900c6ba><br data-v-a900c6ba> 真正有效的 Loop 需要一个<strong data-v-a900c6ba>独立的评判视角</strong>，一个从外部审视生成结果的角色。这正是第二代引入<strong data-v-a900c6ba>独立对抗性 Agent</strong>的根本原因：不是&quot;一个模型多跑几遍&quot;，而是&quot;两个不同的模型互相制衡&quot;。 </p><div class="highlight-box" style="margin-top:16px;background:var(--feature-bg);border-left-color:var(--feature);" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>其实第一代就是一个&quot;Loop&quot;——只是人在环中：</strong></p><p data-v-a900c6ba> 第一代的实际工作流程是 <strong data-v-a900c6ba>AI生成 → 人工检查 → AI修改 → 人工再确认</strong>，本质上就是一个&quot;生成→验证→修订&quot;的循环。这正是现在流行的 <strong data-v-a900c6ba>Human-in-the-Loop (HITL)</strong> 模式。<br data-v-a900c6ba><br data-v-a900c6ba> 第二代的突破在于：<strong data-v-a900c6ba>把人工审查角色替换为一个独立的对抗性 AI Agent</strong>，将 HITL 升级为全自动的 <strong data-v-a900c6ba>Agentic Loop</strong>。人的角色从&quot;苦力审查员&quot;转变为&quot;最终验收者&quot;，只在 AI 无法自行解决的边缘情况下介入。 </p></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>什么是 LangGraph？</h2><p data-v-a900c6ba> LangGraph 是一个<strong data-v-a900c6ba>工作流编排工具</strong>，可以把它想象成一个&quot;智能项目经理&quot;。 </p><div class="highlight-box" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>打个比方：</strong></p><p data-v-a900c6ba> 如果把AI比作员工，传统方式是让一个员工做完所有事情（容易累、容易出错）。<br data-v-a900c6ba> 而LangGraph就像一个项目经理，它能：<br data-v-a900c6ba> ✓ 安排多个专业员工各司其职（布局专家、样式专家、验证专家）<br data-v-a900c6ba> ✓ 决定谁先做、谁后做，哪些可以同时做<br data-v-a900c6ba> ✓ 让审查员工检查其他员工的成果，发现问题就重做<br data-v-a900c6ba> ✓ 记录每个环节的工作日志，出问题能追溯 </p></div><h3 style="margin-top:20px;" data-v-a900c6ba>适合什么场景？</h3><p data-v-a900c6ba>LangGraph 特别适合<strong data-v-a900c6ba>复杂、多步骤、需要质量保证的AI任务</strong>：</p><ul data-v-a900c6ba><li data-v-a900c6ba>✓ <strong data-v-a900c6ba>代码生成</strong>：需要多轮优化和验证，不能一次成型</li><li data-v-a900c6ba>✓ <strong data-v-a900c6ba>文档处理</strong>：提取→分析→总结→校验，环环相扣</li><li data-v-a900c6ba>✓ <strong data-v-a900c6ba>数据分析</strong>：采集→清洗→建模→验证，步骤清晰</li><li data-v-a900c6ba>✓ <strong data-v-a900c6ba>客服系统</strong>：理解问题→查询知识库→生成回复→质量检查</li></ul><p style="margin-top:16px;" data-v-a900c6ba><strong data-v-a900c6ba>不适合的场景：</strong>简单的一问一答、单步骤任务（比如翻译一句话、总结一段文字）， 用传统方式更快更经济。 </p></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>架构示意图</h2><div class="architecture-diagram collaborative" data-v-a900c6ba><div class="arch-title" data-v-a900c6ba>多角色协作 + 精修 + 对抗验证</div><div class="arch-layer" data-v-a900c6ba><div class="layer-title" data-v-a900c6ba>阶段1：Figma 数据获取 + Vision 分析</div><div class="arch-flow" data-v-a900c6ba><div class="arch-node parallel" data-v-a900c6ba>Figma Connector Visual Parser</div></div></div><div class="arch-arrow-down" data-v-a900c6ba>↓</div><div class="arch-layer" data-v-a900c6ba><div class="layer-title" data-v-a900c6ba>阶段2：审查 + 代码生成</div><div class="arch-flow multi" data-v-a900c6ba><div class="arch-node agent" data-v-a900c6ba>Layout Reviewer</div><div class="arch-node agent" data-v-a900c6ba>Style Mapper</div><div class="arch-node agent" data-v-a900c6ba>Microcode Eng.</div></div></div><div class="arch-arrow-down" data-v-a900c6ba>↓</div><div class="arch-layer" data-v-a900c6ba><div class="layer-title" data-v-a900c6ba>阶段3：精修（新增）</div><div class="arch-flow multi" data-v-a900c6ba><div class="arch-node" style="background:linear-gradient(135deg, var(--warning-light) 0%, var(--c-yellow-400) 100%);color:var(--bg-card);border-color:var(--warning-light);" data-v-a900c6ba>Layout Refiner</div><div class="arch-arrow" data-v-a900c6ba>→</div><div class="arch-node" style="background:linear-gradient(135deg, var(--c-purple-500) 0%, var(--c-pink-400) 100%);color:var(--bg-card);border-color:var(--c-purple-500);" data-v-a900c6ba>Style Refiner</div></div></div><div class="arch-arrow-down" data-v-a900c6ba>↓</div><div class="arch-layer" data-v-a900c6ba><div class="layer-title" data-v-a900c6ba>阶段4：对抗验证 + 迭代修订</div><div class="arch-flow adversarial" data-v-a900c6ba><div class="arch-node validator" data-v-a900c6ba>Adversarial Checker</div><div class="arch-arrow-bidirectional" data-v-a900c6ba>⇄ 不合格打回</div><div class="arch-node generator" data-v-a900c6ba>Microcode Eng.</div></div></div><div class="arch-arrow-down" data-v-a900c6ba>↓</div><div class="arch-layer" data-v-a900c6ba><div class="layer-title" data-v-a900c6ba>阶段5：渲染截图 + 视觉比对</div><div class="arch-flow multi" data-v-a900c6ba><div class="arch-node" style="background:linear-gradient(135deg, var(--c-blue-100) 0%, var(--c-blue-200) 100%);color:var(--text-primary);border-color:var(--c-blue-300);" data-v-a900c6ba>Screenshot Renderer</div><div class="arch-arrow" data-v-a900c6ba>→</div><div class="arch-node" style="background:linear-gradient(135deg, var(--c-teal-100) 0%, var(--c-teal-200) 100%);color:var(--text-primary);border-color:var(--c-teal-300);" data-v-a900c6ba>Visual Comparator</div></div></div><div class="arch-note success" data-v-a900c6ba> ✓ 审查先行 + 代码生成 + 两道精修 + 对抗验证 + 视觉比对，全链路质量保障 </div></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>12个专业化角色详解</h2><p data-v-a900c6ba>系统中实际运行着<strong data-v-a900c6ba>12个</strong>高度专业化的角色（含非AI的 Figma 连接器），按工作流划分为两组。每个角色的模型、温度等配置均来自<b data-v-a900c6ba>实际源代码</b>：</p><div style="margin-top:20px;" data-v-a900c6ba><h3 style="font-size:15px;color:var(--brand);margin-bottom:12px;" data-v-a900c6ba>组件生成工作流（Phase 1/2）— 10 个角色</h3><div class="agent-details" data-v-a900c6ba><div class="agent-card" style="border-left-color:var(--c-purple-500);" data-v-a900c6ba><div class="agent-header" data-v-a900c6ba><span class="agent-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h3 data-v-a900c6ba>Figma 连接器</h3><span class="agent-tag" data-v-a900c6ba>FigmaConnector</span></div></div><p class="agent-desc" data-v-a900c6ba>非 AI 角色，纯数据获取。连接 Figma API 下载设计稿数据和图片资源，启用缓存避免重复请求</p><div class="agent-meta" data-v-a900c6ba><span class="meta-item type-none" data-v-a900c6ba>类型: 非AI · 数据获取</span><span class="meta-item" data-v-a900c6ba>缓存: 开启</span></div></div><div class="agent-card" style="border-left-color:var(--c-purple-500);" data-v-a900c6ba><div class="agent-header" data-v-a900c6ba><span class="agent-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h3 data-v-a900c6ba>视觉解析师</h3><span class="agent-tag" data-v-a900c6ba>VisualParser</span></div></div><p class="agent-desc" data-v-a900c6ba>使用 Vision AI 分析预览图 / Figma 截图，提取布局结构、视觉元素和交互信息</p><div class="agent-meta" data-v-a900c6ba><span class="meta-item model-qwen" data-v-a900c6ba>模型: Qwen (Vision)</span><span class="meta-item" data-v-a900c6ba>温度: 0</span><span class="meta-item" data-v-a900c6ba>来源: src/roles/visual-parser.js</span></div></div><div class="agent-card" style="border-left-color:var(--warning-light);" data-v-a900c6ba><div class="agent-header" data-v-a900c6ba><span class="agent-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h3 data-v-a900c6ba>布局审查师</h3><span class="agent-tag" data-v-a900c6ba>LayoutReviewer</span></div></div><p class="agent-desc" data-v-a900c6ba>审查视觉解析师输出的布局结构，发现嵌套层级、定位方式、响应式适配等潜在问题</p><div class="agent-meta" data-v-a900c6ba><span class="meta-item" data-v-a900c6ba>模型: Claude Sonnet 4.6</span><span class="meta-item" data-v-a900c6ba>温度: 0</span><span class="meta-item" data-v-a900c6ba>来源: src/roles/layout-reviewer.js</span></div></div><div class="agent-card" style="border-left-color:var(--success-light);" data-v-a900c6ba><div class="agent-header" data-v-a900c6ba><span class="agent-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h3 data-v-a900c6ba>样式映射师</h3><span class="agent-tag" data-v-a900c6ba>StyleMapper</span></div></div><p class="agent-desc" data-v-a900c6ba>将视觉元素映射为 CSS/Less 代码，输出主题变量、CSS 类名和 Design Token 覆盖度报告</p><div class="agent-meta" data-v-a900c6ba><span class="meta-item" data-v-a900c6ba>模型: Claude Sonnet 4.6</span><span class="meta-item" data-v-a900c6ba>温度: 0</span><span class="meta-item" data-v-a900c6ba>来源: src/roles/style-mapper.js</span></div></div><div class="agent-card" style="border-left-color:var(--warning-light);" data-v-a900c6ba><div class="agent-header" data-v-a900c6ba><span class="agent-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h3 data-v-a900c6ba>布局精修师</h3><span class="agent-tag" data-v-a900c6ba>LayoutRefiner</span><span class="badge-new" data-v-a900c6ba>新增</span></div></div><p class="agent-desc" data-v-a900c6ba>基于 Figma Auto Layout 数据精确还原 CSS 布局：flex 方向、主轴/交叉轴对齐、按 bbox 比例分配尺寸、padding/gap/margin 精确取值</p><div class="agent-meta" data-v-a900c6ba><span class="meta-item" data-v-a900c6ba>模型: Claude Sonnet 4.6</span><span class="meta-item" data-v-a900c6ba>温度: 0</span><span class="meta-item" data-v-a900c6ba>来源: src/roles/layout-refiner.js</span></div></div><div class="agent-card highlighted-role" style="border-left-color:var(--error);" data-v-a900c6ba><div class="agent-header" data-v-a900c6ba><span class="agent-icon" data-v-a900c6ba>‍</span><div data-v-a900c6ba><h3 data-v-a900c6ba>微码工程师</h3><span class="agent-tag" data-v-a900c6ba>MicrocodeEngineer</span><span class="badge-core" data-v-a900c6ba>核心</span></div></div><p class="agent-desc" data-v-a900c6ba>真正<strong data-v-a900c6ba>生成 Vue 组件代码</strong>的角色。加载微码规范、代码模式和声明约束，Figma 阶段自动注入 figma.md 精修规则，输出完整组件文件集合</p><div class="agent-meta" data-v-a900c6ba><span class="meta-item" data-v-a900c6ba>模型: Claude Sonnet 4.6</span><span class="meta-item" data-v-a900c6ba>温度: 0</span><span class="meta-item" data-v-a900c6ba>来源: src/roles/microcode-engineer.js</span></div></div><div class="agent-card" style="border-left-color:var(--c-purple-500);" data-v-a900c6ba><div class="agent-header" data-v-a900c6ba><span class="agent-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h3 data-v-a900c6ba>样式精修师</h3><span class="agent-tag" data-v-a900c6ba>StyleRefiner</span><span class="badge-new" data-v-a900c6ba>新增</span></div></div><p class="agent-desc" data-v-a900c6ba>基于 Figma fills/effects/strokes 精确还原 CSS 样式：颜色（r*255 精确转换）、阴影（offset+radius+spread）、边框、圆角、字体，零臆造原则</p><div class="agent-meta" data-v-a900c6ba><span class="meta-item" data-v-a900c6ba>模型: Claude Sonnet 4.6</span><span class="meta-item" data-v-a900c6ba>温度: 0</span><span class="meta-item" data-v-a900c6ba>来源: src/roles/style-refiner.js</span></div></div><div class="agent-card highlighted-role" style="border-left-color:var(--error-text);" data-v-a900c6ba><div class="agent-header" data-v-a900c6ba><span class="agent-icon" data-v-a900c6ba>⚔️</span><div data-v-a900c6ba><h3 data-v-a900c6ba>对抗性检查师</h3><span class="agent-tag" data-v-a900c6ba>AdversarialChecker</span><span class="badge-core" data-v-a900c6ba>核心</span></div></div><p class="agent-desc" data-v-a900c6ba>从<strong data-v-a900c6ba>批判性视角</strong>对照原设计稿检查生成代码，输出质量评分和修订建议，不合格则触发 L2 修订循环打回重做</p><div class="agent-meta" data-v-a900c6ba><span class="meta-item" data-v-a900c6ba>模型: Claude Sonnet 4.6</span><span class="meta-item" data-v-a900c6ba>温度: 0</span><span class="meta-item" data-v-a900c6ba>来源: src/roles/adversarial-checker.js</span></div></div><div class="agent-card" style="border-left-color:var(--c-blue-300);" data-v-a900c6ba><div class="agent-header" data-v-a900c6ba><span class="agent-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h3 data-v-a900c6ba>渲染截图师</h3><span class="agent-tag" data-v-a900c6ba>ScreenshotRenderer</span><span class="badge-new" data-v-a900c6ba>新增</span></div></div><p class="agent-desc" data-v-a900c6ba>非 AI 角色，使用 <strong data-v-a900c6ba>Puppeteer 无头浏览器</strong>将生成的组件代码渲染为 PNG 截图。优先走前端 Vue 运行时预览页（支持动态内容），失败时降级为静态抽取渲染</p><div class="agent-meta" data-v-a900c6ba><span class="meta-item type-none" data-v-a900c6ba>类型: 非AI · 渲染引擎</span><span class="meta-item" data-v-a900c6ba>引擎: Puppeteer / Chromium</span><span class="meta-item" data-v-a900c6ba>来源: src/roles/screenshot-renderer.js</span></div></div><div class="agent-card" style="border-left-color:var(--c-teal-500);" data-v-a900c6ba><div class="agent-header" data-v-a900c6ba><span class="agent-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h3 data-v-a900c6ba>视觉比对师</h3><span class="agent-tag" data-v-a900c6ba>VisualComparator</span><span class="badge-new" data-v-a900c6ba>新增</span></div></div><p class="agent-desc" data-v-a900c6ba>将 <strong data-v-a900c6ba>Figma 原图</strong>和<strong data-v-a900c6ba>渲染截图</strong>同时交给 Vision AI，从颜色、间距、布局、元素完整性等 7 个维度输出结构化差异报告（含相似度评分、问题列表、是否通过）</p><div class="agent-meta" data-v-a900c6ba><span class="meta-item model-qwen" data-v-a900c6ba>模型: Qwen (Vision)</span><span class="meta-item" data-v-a900c6ba>温度: 0</span><span class="meta-item" data-v-a900c6ba>来源: src/roles/visual-comparator.js</span></div></div></div></div><div style="margin-top:28px;" data-v-a900c6ba><h3 style="font-size:15px;color:var(--c-purple-500);margin-bottom:12px;" data-v-a900c6ba>文档配置工作流 — 2 个 Agent</h3><div class="agent-details" data-v-a900c6ba><div class="agent-card" style="border-left-color:var(--c-purple-500);" data-v-a900c6ba><div class="agent-header" data-v-a900c6ba><span class="agent-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h3 data-v-a900c6ba>文档分析师</h3><span class="agent-tag" data-v-a900c6ba>DocAnalyzerAgent</span></div></div><p class="agent-desc" data-v-a900c6ba>分析微码组件需求文档，提取页面元素、交互设计和接口配置等关键信息</p><div class="agent-meta" data-v-a900c6ba><span class="meta-item" data-v-a900c6ba>模型: Claude 3.5 Sonnet</span><span class="meta-item" data-v-a900c6ba>温度: 0.3</span><span class="meta-item" data-v-a900c6ba>来源: src/agents/doc-analyzer-agent.js</span></div></div><div class="agent-card" style="border-left-color:var(--c-teal-500);" data-v-a900c6ba><div class="agent-header" data-v-a900c6ba><span class="agent-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h3 data-v-a900c6ba>配置生成师</h3><span class="agent-tag" data-v-a900c6ba>ConfigGeneratorAgent</span></div></div><p class="agent-desc" data-v-a900c6ba>基于文档分析结果，自动生成 declare.json 的 businessEvents、businessStatuses、businessConfig、cssVariableConfig 四个配置章节</p><div class="agent-meta" data-v-a900c6ba><span class="meta-item" data-v-a900c6ba>模型: Claude 3.5 Sonnet</span><span class="meta-item" data-v-a900c6ba>温度: 0.3</span><span class="meta-item" data-v-a900c6ba>来源: src/agents/config-generator-agent.js</span></div></div></div></div><div class="highlight-box" style="margin-top:20px;background:var(--brand-bg);border-left-color:var(--brand);" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>专业化分工的优势：</strong></p><p data-v-a900c6ba><strong data-v-a900c6ba>职责单一</strong>：每个 Agent 只做一件事，代码生成质量和一致性远高于单 Agent 模式<br data-v-a900c6ba><strong data-v-a900c6ba>先审后写</strong>：布局审查师 + 样式映射师先行分析，微码工程师基于结构化分析结果生成代码<br data-v-a900c6ba> ⚔️ <strong data-v-a900c6ba>对抗闭环</strong>：对抗性检查师独立验证生成结果，不合格自动打回，形成质量闭环<br data-v-a900c6ba><strong data-v-a900c6ba>双 Provider 路由</strong>：视觉任务走 Qwen，文本任务走 Claude，资源按需分配<br data-v-a900c6ba><strong data-v-a900c6ba>数据可溯源</strong>：每个 Agent 标注了实际源代码位置，所见即所得 </p></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>LangGraph 第二代架构（ing）</h2><p data-v-a900c6ba>第二代系统引入<strong data-v-a900c6ba>多智能体协作 + 并行处理 + 对抗验证</strong>，工作流程如下：</p><div class="process-flow" data-v-a900c6ba><div class="flow-step" data-v-a900c6ba><span class="step-num" data-v-a900c6ba>1</span><div class="step-content" data-v-a900c6ba><h3 data-v-a900c6ba>Figma 阶段（合并优化）</h3><p data-v-a900c6ba><strong data-v-a900c6ba>并行处理</strong>：同时下载预览图和获取节点数据，节省时间</p><p data-v-a900c6ba><strong data-v-a900c6ba>预处理分析</strong>：清理冗余节点，优化数据结构</p><p data-v-a900c6ba><strong data-v-a900c6ba>节点规则检查</strong>：验证根节点bg/header等是否符合规范</p><small data-v-a900c6ba>原先的Preview + Figma两阶段合并为一个，效率提升50%</small></div></div><div class="flow-arrow" data-v-a900c6ba>↓</div><div class="flow-step" data-v-a900c6ba><span class="step-num" data-v-a900c6ba>2</span><div class="step-content" data-v-a900c6ba><h3 data-v-a900c6ba>代码生成 + 精修阶段（先审后写 + 两道精修）</h3><p data-v-a900c6ba><strong data-v-a900c6ba>LayoutReviewer</strong>：审查布局结构，发现嵌套、定位等潜在问题</p><p data-v-a900c6ba><strong data-v-a900c6ba>StyleMapper</strong>：将视觉元素映射为 CSS/Less 变量</p><p data-v-a900c6ba>‍<strong data-v-a900c6ba>MicrocodeEngineer</strong>：基于审查结果 + figma.md 规则生成完整组件代码</p><p data-v-a900c6ba><strong data-v-a900c6ba>LayoutRefiner</strong>：Auto Layout → CSS 布局精修（flex/position/gap/padding）</p><p data-v-a900c6ba><strong data-v-a900c6ba>StyleRefiner</strong>：fills/effects/strokes → CSS 样式精修（颜色/字体/阴影/圆角）</p><small data-v-a900c6ba>5个专业角色各司其职 + 两道精修工序，质量远超单一 AI</small></div></div><div class="flow-arrow" data-v-a900c6ba>↓</div><div class="flow-step" data-v-a900c6ba><span class="step-num" data-v-a900c6ba>3</span><div class="step-content" data-v-a900c6ba><h3 data-v-a900c6ba>验证阶段（对抗式检查）</h3><p data-v-a900c6ba>⚔️ <strong data-v-a900c6ba>独立验证Agent</strong>：像&quot;审查官&quot;一样挑刺，找出生成代码的问题</p><p data-v-a900c6ba><strong data-v-a900c6ba>自动修复循环</strong>：发现问题后自动调用生成Agent修复，最多1次修订</p><p data-v-a900c6ba>✓ <strong data-v-a900c6ba>质量确认</strong>：通过所有检查才输出最终代码</p><small data-v-a900c6ba>对抗式验证机制，准确率从50%提升至85%</small></div></div><div class="flow-arrow" data-v-a900c6ba>↓</div><div class="flow-step" data-v-a900c6ba><span class="step-num" data-v-a900c6ba>4</span><div class="step-content" data-v-a900c6ba><h3 data-v-a900c6ba>视觉比对阶段（渲染 + 像素级校验）</h3><p data-v-a900c6ba><strong data-v-a900c6ba>ScreenshotRenderer</strong>：用 Puppeteer 无头浏览器将生成代码渲染为 PNG 截图</p><p data-v-a900c6ba><strong data-v-a900c6ba>VisualComparator</strong>：将 Figma 原图和渲染截图交给 Vision AI，从颜色、间距、布局等 7 个维度输出差异报告</p><p data-v-a900c6ba><strong data-v-a900c6ba>结构化输出</strong>：包含相似度评分、分级问题列表、是否通过的结论</p><small data-v-a900c6ba>端到端视觉还原度校验，像素级保障</small></div></div></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>循环（Loop）概念 — 架构的核心闭环机制</h2><p data-v-a900c6ba> Loop 不是单一概念，而是<strong data-v-a900c6ba>三层循环体系</strong>，每一层解决不同粒度的问题。这是 LangGraph 架构区别于线性工作流的核心特征。 </p><div class="loop-layers" style="margin-top:20px;" data-v-a900c6ba><div class="loop-layer" data-v-a900c6ba><div class="layer-header" data-v-a900c6ba><div class="layer-badge l1" data-v-a900c6ba>L1</div><div class="layer-title-group" data-v-a900c6ba><h3 data-v-a900c6ba>图引擎循环 — 基础设施</h3><span class="layer-tag" data-v-a900c6ba>graph.js</span></div></div><div class="layer-body" data-v-a900c6ba><div class="layer-code-block" data-v-a900c6ba><code data-v-a900c6ba>while (currentNode &amp;&amp; iterations &lt; maxIterations) { // maxIterations = 100 await this.executeNode(currentNode) currentNode = this.getNextNode(currentNode) }</code></div><p data-v-a900c6ba>所有图（Phase1 / Phase2 / 动态工作流）的<strong data-v-a900c6ba>底层运行时</strong>。通过 <code data-v-a900c6ba>while</code> 循环不断推进节点，当条件边返回已执行过的节点名称时，<code data-v-a900c6ba>getNextNode()</code> 就让 while 循环回到该节点，<strong data-v-a900c6ba>天然支持回边/循环</strong>。</p><div class="layer-features" data-v-a900c6ba><span class="feature-tag" data-v-a900c6ba>所有图共用</span><span class="feature-tag" data-v-a900c6ba>硬上限 100 次</span><span class="feature-tag" data-v-a900c6ba>支持条件边回边</span><span class="feature-tag" data-v-a900c6ba>防死循环安全网</span></div></div></div><div class="loop-layer highlighted" data-v-a900c6ba><div class="layer-header" data-v-a900c6ba><div class="layer-badge l2" data-v-a900c6ba>L2</div><div class="layer-title-group" data-v-a900c6ba><h3 data-v-a900c6ba>修订迭代循环 — 核心业务循环</h3><span class="layer-tag" data-v-a900c6ba>Phase2 图 · Figma 精修阶段</span></div></div><div class="layer-body" data-v-a900c6ba><div class="architecture-diagram collaborative" style="margin:16px 0;padding:16px;" data-v-a900c6ba><div class="arch-flow adversarial" style="justify-content:center;gap:8px;flex-wrap:wrap;" data-v-a900c6ba><div class="arch-node agent" style="font-size:12px;padding:8px 12px;" data-v-a900c6ba>microcode-engineer<br data-v-a900c6ba><small data-v-a900c6ba>代码生成</small></div><span style="font-size:18px;color:var(--text-tertiary);" data-v-a900c6ba>→</span><div class="arch-node validator" style="font-size:12px;padding:8px 12px;" data-v-a900c6ba>adversarial-checker<br data-v-a900c6ba><small data-v-a900c6ba>对抗检查</small></div><span style="font-size:18px;color:var(--text-tertiary);" data-v-a900c6ba>→</span><div style="background:var(--c-orange-100);border:2px solid var(--warning-light);border-radius:var(--radius-md);padding:8px 12px;font-size:12px;text-align:center;" data-v-a900c6ba><strong data-v-a900c6ba>revision-decision</strong><br data-v-a900c6ba><small data-v-a900c6ba>判断是否修订</small></div></div><div style="display:flex;justify-content:center;align-items:center;gap:12px;margin-top:12px;font-size:13px;" data-v-a900c6ba><span style="color:var(--error);font-weight:600;" data-v-a900c6ba>← needs_revision 回边</span><span style="color:var(--text-tertiary);" data-v-a900c6ba>|</span><span style="color:var(--success-light);font-weight:600;" data-v-a900c6ba>→ 通过则结束</span></div></div><p data-v-a900c6ba>这是你在<strong data-v-a900c6ba>实际生成组件时看到的效果</strong>：&quot;生成 → 检查 → 修订 → 重新检查&quot; 的迭代过程。</p><table class="loop-detail-table" data-v-a900c6ba><thead data-v-a900c6ba><tr data-v-a900c6ba><th data-v-a900c6ba>维度</th><th data-v-a900c6ba>说明</th></tr></thead><tbody data-v-a900c6ba><tr data-v-a900c6ba><td data-v-a900c6ba>循环触发</td><td data-v-a900c6ba><code data-v-a900c6ba>checkResult === &#39;needs_revision&#39;</code> 且未达最大次数</td></tr><tr data-v-a900c6ba><td data-v-a900c6ba>每轮变化</td><td data-v-a900c6ba><code data-v-a900c6ba>iterationCount++</code>，将上次检查的 <code data-v-a900c6ba>critiques</code> 传给生成 Agent 作为修订指导</td></tr><tr data-v-a900c6ba><td data-v-a900c6ba>退出条件</td><td data-v-a900c6ba>检查通过，或达到 <code data-v-a900c6ba>maxIterations=1</code>（1 次生成 + 1 次修订 = 共 2 轮）</td></tr><tr data-v-a900c6ba><td data-v-a900c6ba>实际位置</td><td data-v-a900c6ba><code data-v-a900c6ba>mc-component-graph-phase2.js</code> 第 544-548 行的条件边</td></tr></tbody></table></div></div><div class="loop-layer" data-v-a900c6ba><div class="layer-header" data-v-a900c6ba><div class="layer-badge l3" data-v-a900c6ba>L3</div><div class="layer-title-group" data-v-a900c6ba><h3 data-v-a900c6ba>节点级重试循环 — 容错机制</h3><span class="layer-tag" data-v-a900c6ba>Orchestrator · 动态工作流</span></div></div><div class="layer-body" data-v-a900c6ba><div class="layer-code-block" data-v-a900c6ba><code data-v-a900c6ba>// orchestrator.js withRetry() function withRetry(fn, { maxRetries = 2 }) { for (let attempt = 0; attempt &lt;= maxRetries; attempt++) { try { return await fn(state) } catch (err) { console.warn(`[Retry ${attempt + 1}/${maxRetries}] ${err.message}`) await sleep(attempt * 2000) // 等待后重试 } } }</code></div><p data-v-a900c6ba><strong data-v-a900c6ba>与 L2 图级循环是不同维度的</strong>：L3 不改变业务状态，仅在网络异常或 AI 调用失败时自动重试。</p><table class="loop-detail-table" data-v-a900c6ba><thead data-v-a900c6ba><tr data-v-a900c6ba><th data-v-a900c6ba>对比</th><th data-v-a900c6ba>L2 修订迭代（图级）</th><th data-v-a900c6ba>L3 节点重试（Orchestrator）</th></tr></thead><tbody data-v-a900c6ba><tr data-v-a900c6ba><td data-v-a900c6ba>触发原因</td><td data-v-a900c6ba>代码质量不达标</td><td data-v-a900c6ba>网络 / AI 调用异常</td></tr><tr data-v-a900c6ba><td data-v-a900c6ba>状态变化</td><td data-v-a900c6ba>iterationCount++，传入新 critiques</td><td data-v-a900c6ba>不改变 state</td></tr><tr data-v-a900c6ba><td data-v-a900c6ba>当前使用者</td><td data-v-a900c6ba>Phase2 图</td><td data-v-a900c6ba>动态工作流图</td></tr></tbody></table></div></div></div><div class="highlight-box" style="margin-top:20px;background:var(--feature-bg);border-left-color:var(--feature);" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>多层安全网：</strong></p><p data-v-a900c6ba><strong data-v-a900c6ba>L1 图引擎 maxIterations=100</strong>：防死循环的硬上限<br data-v-a900c6ba><strong data-v-a900c6ba>L2 Phase2 maxIterations=2</strong>：业务层修订次数上限<br data-v-a900c6ba><strong data-v-a900c6ba>axios timeout=300000</strong>：单次 API 调用 5 分钟超时<br data-v-a900c6ba><strong data-v-a900c6ba>Promise.race 超时</strong>：视觉分析节点级超时保护<br data-v-a900c6ba><strong data-v-a900c6ba>L3 withRetry maxRetries=2</strong>：节点异常自动重试 </p></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>预期效果提升</h2><div class="comparison-table" data-v-a900c6ba><table data-v-a900c6ba><thead data-v-a900c6ba><tr data-v-a900c6ba><th data-v-a900c6ba>指标</th><th data-v-a900c6ba>第一代</th><th data-v-a900c6ba>第二代</th></tr></thead><tbody data-v-a900c6ba><tr data-v-a900c6ba><td data-v-a900c6ba>简单组件准确率</td><td data-v-a900c6ba>~80%</td><td data-v-a900c6ba><strong data-v-a900c6ba>~95%</strong></td></tr><tr data-v-a900c6ba><td data-v-a900c6ba>复杂组件准确率</td><td data-v-a900c6ba>~50%</td><td data-v-a900c6ba><strong data-v-a900c6ba>~90%</strong></td></tr><tr data-v-a900c6ba><td data-v-a900c6ba>需要人工修正</td><td data-v-a900c6ba>60%的情况</td><td data-v-a900c6ba><strong data-v-a900c6ba>15%的情况</strong></td></tr><tr data-v-a900c6ba><td data-v-a900c6ba>生成时间</td><td data-v-a900c6ba>30-60秒</td><td data-v-a900c6ba>120-240秒</td></tr><tr data-v-a900c6ba><td data-v-a900c6ba>视觉还原度</td><td data-v-a900c6ba>无自动检测</td><td data-v-a900c6ba><strong data-v-a900c6ba>AI自动比对</strong></td></tr><tr data-v-a900c6ba><td data-v-a900c6ba>验证器数量</td><td data-v-a900c6ba>0</td><td data-v-a900c6ba><strong data-v-a900c6ba>26个专项验证</strong></td></tr></tbody></table></div><p class="note" data-v-a900c6ba> * 第二代虽然时间稍长，但质量大幅提升，综合效率更高 </p></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>架构亮点总结</h2><p data-v-a900c6ba>第二代架构不只是&quot;换了个框架&quot;，而是一次从<strong data-v-a900c6ba>单打独斗到多智能体协作</strong>、从<strong data-v-a900c6ba>脚本编排到图引擎驱动</strong>、从<strong data-v-a900c6ba>本地工具到云端平台</strong>的全面跃迁。</p><div class="highlights-grid" style="margin-top:20px;" data-v-a900c6ba><div class="highlight-card core" data-v-a900c6ba><div class="hl-number" data-v-a900c6ba>1</div><div class="hl-content" data-v-a900c6ba><h3 data-v-a900c6ba>⚔️ 对抗性闭环 <span class="badge-core-highlight" data-v-a900c6ba>核心</span></h3><p data-v-a900c6ba>独立验证 Agent 拿着 Figma 原图对照代码挑刺，发现问题<strong data-v-a900c6ba>自动打回重做</strong>，形成&quot;生成→检查→修订→再检查&quot;的闭环。不是&quot;写完检查一下&quot;，而是<strong data-v-a900c6ba>开发/测试互相制衡</strong>。</p><span class="hl-keyword" data-v-a900c6ba>制衡</span></div></div><div class="highlight-card core" data-v-a900c6ba><div class="hl-number" data-v-a900c6ba>2</div><div class="hl-content" data-v-a900c6ba><h3 data-v-a900c6ba>三层 Loop 容错体系 <span class="badge-core-highlight" data-v-a900c6ba>核心</span></h3><p data-v-a900c6ba>图引擎层支持条件回边 + 业务层修订迭代循环 + 节点层异常重试，架构<strong data-v-a900c6ba>自带容错和自愈能力</strong>，不死循环、不静默挂起。</p><span class="hl-keyword" data-v-a900c6ba>自愈</span></div></div><div class="highlight-card core" data-v-a900c6ba><div class="hl-number" data-v-a900c6ba>3</div><div class="hl-content" data-v-a900c6ba><h3 data-v-a900c6ba>专业化分工 + 模型按需分配 <span class="badge-core-highlight" data-v-a900c6ba>核心</span></h3><p data-v-a900c6ba>12 个角色各司其职（视觉解析/布局审查/样式映射/代码生成/布局精修/样式精修/对抗检查/渲染截图/视觉比对/文档分析/配置生成），视觉任务走 Qwen、文本任务走 Claude，双 Provider 独立路由。</p><span class="hl-keyword" data-v-a900c6ba>分工</span></div></div><div class="highlight-card" data-v-a900c6ba><div class="hl-number" data-v-a900c6ba>4</div><div class="hl-content" data-v-a900c6ba><h3 data-v-a900c6ba>☁️ 独立云端服务</h3><p data-v-a900c6ba>从绑死在项目目录的本地脚本，变为独立 Web 服务。HTTP API 调用、多用户并发、SSE 实时推送、负载均衡高可用，<strong data-v-a900c6ba>从个人工具到企业平台</strong>。</p><span class="hl-keyword" data-v-a900c6ba>平台</span></div></div><div class="highlight-card" data-v-a900c6ba><div class="hl-number" data-v-a900c6ba>5</div><div class="hl-content" data-v-a900c6ba><h3 data-v-a900c6ba>统一图引擎，编排即执行</h3><p data-v-a900c6ba>同一套 <code data-v-a900c6ba>Graph</code> 引擎驱动所有工作流（组件生成/文档配置/代码生成/批量调度）。前端画布编排的 JSON 可直接反序列化为可执行图，<strong data-v-a900c6ba>新工作流不需要写引擎代码</strong>。</p><span class="hl-keyword" data-v-a900c6ba>复用</span></div></div><div class="highlight-card" data-v-a900c6ba><div class="hl-number" data-v-a900c6ba>6</div><div class="hl-content" data-v-a900c6ba><h3 data-v-a900c6ba>三层可观测性</h3><p data-v-a900c6ba>结构化日志自动关联 sessionId → SSE 实时推送到前端 → 任务状态持久化 + 断线重连。关闭浏览器再打开，通过 sessionId <strong data-v-a900c6ba>照样看到完整进度</strong>。</p><span class="hl-keyword" data-v-a900c6ba>可观测</span></div></div><div class="highlight-card" data-v-a900c6ba><div class="hl-number" data-v-a900c6ba>7</div><div class="hl-content" data-v-a900c6ba><h3 data-v-a900c6ba>Agent 可插拔配置</h3><p data-v-a900c6ba>每个节点可独立配置 model / temperature / maxTokens，Claude 挂了<strong data-v-a900c6ba>自动降级到 Qwen</strong>，视觉走 Qwen、文本走 Claude 双路由。</p><span class="hl-keyword" data-v-a900c6ba>灵活</span></div></div><div class="highlight-card" data-v-a900c6ba><div class="hl-number" data-v-a900c6ba>8</div><div class="hl-content" data-v-a900c6ba><h3 data-v-a900c6ba>四层错误防护</h3><p data-v-a900c6ba>单节点失败不会拖垮全局：<strong data-v-a900c6ba>自动重试（指数退避）→ 降级备用模型 → 超时熔断（5min）→ 僵尸回收（2h）</strong>，四层渐进式防护。</p><span class="hl-keyword" data-v-a900c6ba>鲁棒</span></div></div><div class="highlight-card" data-v-a900c6ba><div class="hl-number" data-v-a900c6ba>9</div><div class="hl-content" data-v-a900c6ba><h3 data-v-a900c6ba>批量 DAG 调度</h3><p data-v-a900c6ba>多组件间声明 <code data-v-a900c6ba>dependsOn</code> 依赖关系，调度器按拓扑序分层、同层并行执行。自动检测循环依赖，<strong data-v-a900c6ba>中断可恢复</strong>。</p><span class="hl-keyword" data-v-a900c6ba>并行</span></div></div><div class="highlight-card" data-v-a900c6ba><div class="hl-number" data-v-a900c6ba>10</div><div class="hl-content" data-v-a900c6ba><h3 data-v-a900c6ba>可视化导出 + 热重载</h3><p data-v-a900c6ba>图可导出为 Mermaid / JSON 格式，工作流持久化管理。修改代码后 <code data-v-a900c6ba>POST /api/reload</code> 热重载，<strong data-v-a900c6ba>无需重启服务</strong>。</p><span class="hl-keyword" data-v-a900c6ba>迭代</span></div></div></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>可扩展性与未来价值</h2><p data-v-a900c6ba> 当前的LangGraph架构不仅解决了微码组件生成的问题，更重要的是为未来的AI工具开发提供了<strong data-v-a900c6ba>统一的可扩展平台</strong>。 </p><div class="highlight-box" style="margin-top:16px;background:var(--success-bg);border-left-color:var(--success);" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>✓ 已落地的模块：</strong></p><p data-v-a900c6ba><strong data-v-a900c6ba>普通Vue组件生成</strong>：基于Figma设计稿生成标准Vue3组件（独立于微码）<br data-v-a900c6ba><strong data-v-a900c6ba>大屏布局生成</strong>：支持数据可视化大屏的响应式布局开发 </p><p style="margin-top:12px;" data-v-a900c6ba><strong data-v-a900c6ba>正在开发的模块：</strong></p><p data-v-a900c6ba><strong data-v-a900c6ba>Java 业务后端迁移</strong>：Spring Boot 承接用户认证（SSO + JWT）、组织/群组管理、组件元数据、生成记录、Token 配额等，与 Node AI 引擎分工协作<br data-v-a900c6ba><strong data-v-a900c6ba>企业级权限体系</strong>：对接 QS 门户 SSO，实现组织-部门-用户层级同步 + 权限码管理 + 接口级鉴权<br data-v-a900c6ba><strong data-v-a900c6ba>统计看板与评分系统</strong>：8 维生成评分（布局/样式/语义/性能/可读性/规范/对比度/复杂度）+ 按时间/用户/组织维度的统计聚合<br data-v-a900c6ba><strong data-v-a900c6ba>AI 视觉对比分析</strong>：一键对已生成组件做 Figma 原稿 vs 真实预览截图的视觉质检，输出结构化差异报告与下一步建议（接口层已接通） </p><p style="margin-top:12px;" data-v-a900c6ba><strong data-v-a900c6ba>当前迭代优化：</strong></p><p data-v-a900c6ba><strong data-v-a900c6ba>管线性能大幅缩减</strong>：按预估输出智能分块（消除 900s 截断浪费）、按问题类别只修目标文件（不再全量重做）、SFC 事实注入减少误判<br data-v-a900c6ba><strong data-v-a900c6ba>运行时门禁分级</strong>：区分致命失败 / 告警完成 / 增量修订三档，纯缺图场景走自愈 + 降级而非盲目打回重做<br data-v-a900c6ba><strong data-v-a900c6ba>Figma 预览图闭环</strong>：硬约束 <code data-v-a900c6ba>mc-preview.png</code> 标准产出，缺图自动补下载 + Token 来源统一为用户配置<br data-v-a900c6ba><strong data-v-a900c6ba>质量门禁语义化</strong>：区分&quot;质量通过&quot;与&quot;带警告完成&quot;，避免简单组件被过度修订 </p><p style="margin-top:12px;" data-v-a900c6ba><strong data-v-a900c6ba>近期规划：</strong></p><p data-v-a900c6ba><strong data-v-a900c6ba>视觉比对质检恢复</strong>：优化 Vision AI 比对策略（确定性 CSS diff + AI 降级兜底），恢复自动截图-比对-修订闭环<br data-v-a900c6ba><strong data-v-a900c6ba>多模型供应商治理</strong>：去除硬编码依赖，接入 DashScope / MaaS 等兼容端点，主备自动降级 + 额度管控<br data-v-a900c6ba><strong data-v-a900c6ba>组件发布流水线</strong>：生成 → 审核 → 发布到组件库 → NPM 打包，全流程自动化<br data-v-a900c6ba><strong data-v-a900c6ba>高分模板推荐</strong>：基于历史生成数据沉淀成功模式，按组件类型/组织智能推荐最佳实践 </p><p style="margin-top:12px;" data-v-a900c6ba><strong data-v-a900c6ba>远期愿景：</strong></p><p data-v-a900c6ba><strong data-v-a900c6ba>后台管理系统生成</strong>：自动生成包含 CRUD 操作的完整后台管理页面<br data-v-a900c6ba><strong data-v-a900c6ba>模板市场</strong>：跨组织共享高分组件模板，一键复用<br data-v-a900c6ba><strong data-v-a900c6ba>团队效能看板</strong>：AI 节省时间统计 + 采纳率分析 + 团队协作排行 </p></div><h3 style="margin-top:20px;" data-v-a900c6ba>架构复用能力</h3><div class="innovation-grid" data-v-a900c6ba><div class="innovation-card" style="background:var(--brand-bg);" data-v-a900c6ba><div class="icon" data-v-a900c6ba>♻️</div><h3 data-v-a900c6ba>节点复用</h3><p data-v-a900c6ba>当前的Figma连接器、代码生成器、验证器可以在所有新模块中复用，无需重复开发。</p></div><div class="innovation-card" style="background:var(--feature-bg);" data-v-a900c6ba><div class="icon" data-v-a900c6ba></div><h3 data-v-a900c6ba>模式复用</h3><p data-v-a900c6ba>并行处理、对抗验证、循环修复等成熟工作流模式可以套用到任何新工具。</p></div><div class="innovation-card" style="background:var(--warning-bg);" data-v-a900c6ba><div class="icon" data-v-a900c6ba></div><h3 data-v-a900c6ba>基础设施统一</h3><p data-v-a900c6ba>进度推送、日志系统、状态管理、错误处理等基础设施在所有模块间共享。</p></div><div class="innovation-card" style="background:var(--success-bg);" data-v-a900c6ba><div class="icon" data-v-a900c6ba></div><h3 data-v-a900c6ba>快速开发</h3><p data-v-a900c6ba>每个新模块只需定义专用节点，然后连接成工作流，开发成本随共享组件增加而降低。</p></div></div><div class="highlight-box" style="margin-top:20px;background:var(--brand-bg);border-left-color:var(--brand);" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>长期价值：</strong></p><p data-v-a900c6ba> LangGraph架构是一个<strong data-v-a900c6ba>AI工具开发平台</strong>，而不仅仅是单一功能。<br data-v-a900c6ba> 随着模块增加，平台价值呈指数级增长，团队生产力持续提升。 </p></div></section>',9)])])):e("",!0),d.value==="tech-comparison"?(c(),s("div",F,[...a[5]||(a[5]=[i('<section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>为什么选择LangGraph？</h2><p data-v-a900c6ba>在设计第二代架构时，我们评估了多个AI编排框架，最终选择了LangGraph。以下是详细的技术选型分析：</p><div class="highlight-box warn" style="margin-top:16px;" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>核心需求：</strong></p><p data-v-a900c6ba> ✓ 支持复杂的<strong data-v-a900c6ba>循环和分支</strong>逻辑（生成→验证→修复→重新验证）<br data-v-a900c6ba> ✓ 灵活的<strong data-v-a900c6ba>状态管理</strong>机制（跨Agent共享数据）<br data-v-a900c6ba> ✓ 可实现<strong data-v-a900c6ba>对抗性验证</strong>循环<br data-v-a900c6ba> ✓ 支持<strong data-v-a900c6ba>并行执行</strong>和条件路由 </p></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>框架对比分析</h2><p data-v-a900c6ba>我们对比了市场上流行的三个AI编排框架：</p><div class="comparison-cards" data-v-a900c6ba><div class="framework-card openclaw" data-v-a900c6ba><div class="framework-header" data-v-a900c6ba><h3 data-v-a900c6ba>OpenClaw</h3><span class="framework-badge" data-v-a900c6ba>工具快速连接器</span></div><div class="framework-content" data-v-a900c6ba><div class="pros-section" data-v-a900c6ba><h4 data-v-a900c6ba>特点</h4><ul data-v-a900c6ba><li data-v-a900c6ba>极致易用，快速连接外部工具（微信、Slack等）</li><li data-v-a900c6ba>社区活跃（2.8万+技能库）</li><li data-v-a900c6ba>灵活的工具集成能力</li></ul></div><div class="cons-section" data-v-a900c6ba><h4 data-v-a900c6ba>不适合我们的场景</h4><ul data-v-a900c6ba><li data-v-a900c6ba><strong data-v-a900c6ba>定位不匹配</strong>：工具连接器，而非流程编排框架</li><li data-v-a900c6ba><strong data-v-a900c6ba>缺乏固化流程</strong>：灵活但不适合需要严格规范的代码生成</li><li data-v-a900c6ba><strong data-v-a900c6ba>不够可控</strong>：适合通用任务，不适合企业级固定流程</li></ul></div></div></div><div class="framework-card langgraph selected" data-v-a900c6ba><div class="framework-header" data-v-a900c6ba><h3 data-v-a900c6ba>LangGraph</h3><span class="framework-badge selected" data-v-a900c6ba>我们的选择</span></div><div class="framework-content" data-v-a900c6ba><div class="pros-section" data-v-a900c6ba><h4 data-v-a900c6ba>优势</h4><ul data-v-a900c6ba><li data-v-a900c6ba><strong data-v-a900c6ba>有向图工作流</strong>：支持复杂分支、循环、并行</li><li data-v-a900c6ba><strong data-v-a900c6ba>状态机模型</strong>：每个节点可读写全局状态</li><li data-v-a900c6ba><strong data-v-a900c6ba>条件路由</strong>：根据验证结果决定下一步</li><li data-v-a900c6ba><strong data-v-a900c6ba>循环支持</strong>：完美实现对抗验证机制</li></ul></div><div class="cons-section" data-v-a900c6ba><h4 data-v-a900c6ba>注意</h4><ul data-v-a900c6ba><li data-v-a900c6ba>学习曲线稍陡（需要理解图和状态机）</li><li data-v-a900c6ba>生态相对年轻（但快速发展中）</li></ul></div></div></div><div class="framework-card hermes" data-v-a900c6ba><div class="framework-header" data-v-a900c6ba><h3 data-v-a900c6ba>Hermes</h3><span class="framework-badge" data-v-a900c6ba>自优化引擎</span></div><div class="framework-content" data-v-a900c6ba><div class="pros-section" data-v-a900c6ba><h4 data-v-a900c6ba>特点</h4><ul data-v-a900c6ba><li data-v-a900c6ba>AI应用超脑明，能从历史任务学习优化</li><li data-v-a900c6ba>动态生成与进化技能，实现&quot;吃一堑长一智&quot;</li><li data-v-a900c6ba>主动选择性记忆，会&quot;更懂你&quot;</li></ul></div><div class="cons-section" data-v-a900c6ba><h4 data-v-a900c6ba>不适合我们的场景</h4><ul data-v-a900c6ba><li data-v-a900c6ba><strong data-v-a900c6ba>过于智能和灵活</strong>：会自我学习、优化策略</li><li data-v-a900c6ba><strong data-v-a900c6ba>不适合固定规范</strong>：代码生成需要稳定可预测的输出</li><li data-v-a900c6ba><strong data-v-a900c6ba>缺乏流程控制</strong>：适合推理优化，不适合结构化工作流</li></ul></div></div></div></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>使用方式与部署对比</h2><p data-v-a900c6ba>两代架构在使用方式和部署方式上有本质区别：</p><div class="deployment-comparison" data-v-a900c6ba><div class="deploy-card" data-v-a900c6ba><h3 data-v-a900c6ba>第一代（Skills+Shell）</h3><div class="deploy-method" data-v-a900c6ba><div class="method-item" data-v-a900c6ba><span class="method-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h4 data-v-a900c6ba>集成到项目中</h4><p data-v-a900c6ba>必须将skills和脚本集成到具体项目目录中</p></div></div><div class="method-item" data-v-a900c6ba><span class="method-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h4 data-v-a900c6ba>依赖Claude AI环境</h4><p data-v-a900c6ba>需要Claude Desktop或Claude CLI环境来运行skills</p></div></div><div class="method-item" data-v-a900c6ba><span class="method-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h4 data-v-a900c6ba>本地文件系统</h4><p data-v-a900c6ba>所有状态和中间产物存储在项目目录中</p></div></div><div class="method-item" data-v-a900c6ba><span class="method-icon" data-v-a900c6ba>✕</span><div data-v-a900c6ba><h4 data-v-a900c6ba>无法云端部署</h4><p data-v-a900c6ba>Skills系统依赖本地环境，无法独立部署</p></div></div></div></div><div class="deploy-card highlight" data-v-a900c6ba><h3 data-v-a900c6ba>第二代（LangGraph）</h3><div class="deploy-method" data-v-a900c6ba><div class="method-item" data-v-a900c6ba><span class="method-icon" data-v-a900c6ba>☁️</span><div data-v-a900c6ba><h4 data-v-a900c6ba>独立服务部署</h4><p data-v-a900c6ba>可作为独立的Web服务部署到云端</p></div></div><div class="method-item" data-v-a900c6ba><span class="method-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h4 data-v-a900c6ba>HTTP API访问</h4><p data-v-a900c6ba>通过HTTP API调用，任何客户端都可以使用</p></div></div><div class="method-item" data-v-a900c6ba><span class="method-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h4 data-v-a900c6ba>支持本地部署</h4><p data-v-a900c6ba>也可以在本地运行Node.js服务器</p></div></div><div class="method-item" data-v-a900c6ba><span class="method-icon" data-v-a900c6ba></span><div data-v-a900c6ba><h4 data-v-a900c6ba>多用户并发</h4><p data-v-a900c6ba>云端部署后，多个开发者可同时使用</p></div></div></div></div></div><div class="highlight-box" style="margin-top:20px;background:var(--success-bg);border-left-color:var(--success);" data-v-a900c6ba><p data-v-a900c6ba><strong data-v-a900c6ba>第二代架构的部署优势：</strong></p><p data-v-a900c6ba> ☁️ <strong data-v-a900c6ba>云端部署</strong>：部署到阿里云/AWS/腾讯云，全团队共享<br data-v-a900c6ba><strong data-v-a900c6ba>企业级</strong>：支持负载均衡、高可用、横向扩展<br data-v-a900c6ba><strong data-v-a900c6ba>权限管理</strong>：可以添加用户认证和权限控制<br data-v-a900c6ba><strong data-v-a900c6ba>监控日志</strong>：集中式日志管理和性能监控<br data-v-a900c6ba><strong data-v-a900c6ba>版本控制</strong>：独立版本迭代，不影响项目代码 </p></div></section><section class="section" data-v-a900c6ba><h2 data-v-a900c6ba>总结：为什么LangGraph是更好的选择</h2><div class="summary-grid" data-v-a900c6ba><div class="summary-item" data-v-a900c6ba><span class="summary-icon" data-v-a900c6ba></span><h4 data-v-a900c6ba>固化流程 vs 灵活智能</h4><p data-v-a900c6ba><strong data-v-a900c6ba>核心选型理由</strong>：OpenClaw/Hermes更灵活、更智能（自学习、自优化），但我们需要的是<strong data-v-a900c6ba>固化的流程、固定的规范、可预测的结果</strong>。LangGraph提供强控制的结构化工作流，适合企业级代码生成场景。</p></div><div class="summary-item" data-v-a900c6ba><span class="summary-icon" data-v-a900c6ba></span><h4 data-v-a900c6ba>复杂流程控制</h4><p data-v-a900c6ba>LangGraph的状态机+有向图模型，完美支持&quot;生成→验证→修复→重新验证&quot;的循环逻辑，这是对抗验证的核心需求。</p></div><div class="summary-item" data-v-a900c6ba><span class="summary-icon" data-v-a900c6ba></span><h4 data-v-a900c6ba>多Agent协作</h4><p data-v-a900c6ba>天然支持多个Agent并行工作和状态共享，实现细粒度的专业化分工。</p></div><div class="summary-item" data-v-a900c6ba><span class="summary-icon" data-v-a900c6ba></span><h4 data-v-a900c6ba>企业级可扩展</h4><p data-v-a900c6ba>支持负载均衡、高可用、监控告警等企业级特性，适合生产环境使用。</p></div></div></section>',4)])])):e("",!0),d.value==="topology"?(c(),s("div",R,[...a[6]||(a[6]=[t("section",{class:"section"},[t("h2",null,"平台能力关系拓扑"),t("p",null,"交互式拓扑图，展示全站 32 个模块的 6 层架构关系、55 条连线（5 种类型）和各模块交互点清单。点击节点查看详情，使用图例筛选连线类型。")],-1),t("div",{class:"topology-iframe-wrap"},[t("iframe",{src:"/topology.html",class:"topology-iframe",frameborder:"0"})],-1)])])):e("",!0)])])])}}}),M=w(V,[["__scopeId","data-v-a900c6ba"]]);export{M as default};
